import{_ as i,a0 as s,w as n,s as o,ao as f,I as d,x as e,a1 as a,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"为什么企业应该选择平台即服务（PaaS） | LCTT x X-CMD","titleTemplate":false,"description":"为什么企业应该选择平台即服务（PaaS） | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么企业应该选择平台即服务（PaaS） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么企业应该选择平台即服务（PaaS） | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20220914 Why Enterprises Should  Opt for Platform as a Service","title":"为什么企业应该选择平台即服务（PaaS）","tag":"202302","desc":""},"relativePath":"202302/20220914 Why Enterprises Should  Opt for Platform as a Service.md","filePath":"[post].md"}'),p={name:"202302/20220914 Why Enterprises Should  Opt for Platform as a Service.md"};function y(g,t,u,x,S,P){const l=s("Link");return n(),o("div",null,[t[15]||(t[15]=f('<h1 id="为什么企业应该选择平台即服务-paas" tabindex="-1">为什么企业应该选择平台即服务（PaaS） <a class="header-anchor" href="#为什么企业应该选择平台即服务-paas" aria-label="Permalink to “为什么企业应该选择平台即服务（PaaS）”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/17/094352atasztuxqg4t1ctt.jpg" alt=""></p><blockquote><p>平台即服务能够快速、轻松地创建网络应用，而无需购买和维护其下的软件和基础设施。本文解释了它为什么有用。</p></blockquote><p><ruby>平台即服务<rt>PaaS</rt></ruby>（以下简称 PaaS）指的是云计算服务，它为客户提供了开发、运行和管理应用程序的平台，而免去了建立和维护与开发和启动应用程序相关的基础设施的复杂工作。这是云原生应用和支持系统所依托的核心平台。</p><p>PaaS 通常包括不同的应用基础功能，包括应用平台、集成平台、业务分析平台、事件流服务和移动后端服务。此外，它还包括一套与监控、管理、部署相关的功能。</p><p>开发人员希望他们的开发环境不需要等待，而运营团队则更关心性能和稳定性。这经常引起两方间的冲突。PaaS 为这两方创造了和平的环境。一个作为服务交付的应用平台被称作 PaaS，它被用于部署用户代码。Cloud Foundry、Cloudify 和 OpenShift 这些开源环境都可用作 PaaS。</p><h3 id="paas-的采用模式" tabindex="-1">PaaS 的采用模式 <a class="header-anchor" href="#paas-的采用模式" aria-label="Permalink to “PaaS 的采用模式”">​</a></h3><p>云计算必须满足五个基本特征：按需服务、接入网络、资源池化、弹性和可度量的服务。为此，云计算提供了三种服务模式：<ruby>软件即服务<rt>Software as a Service</rt></ruby>（SaaS）、<ruby>平台即服务<rt>Platform as a Service</rt></ruby>（PaaS）、<ruby>基础设施即服务<rt>Infrastructure as a Service</rt></ruby>（IaaS）。</p><p>业务选用 PaaS 的关键驱动力：</p><ul><li>减少提供业务的资本支出和运营费用</li><li>通过减少应用程序的交付时间和提高开发和交付质量，最大限度地降低 IT 成本</li><li>增加中间件之间的灵活性和集成度</li></ul><p><em>简单 PaaS</em>：踏入 PaaS 领域的入口。它可以提供应用程序服务，并将它们暴露在自助服务的目录中；自动部署和计量服务使用的资源。</p><p><em>管理 PaaS</em>：管理已配置应用程序的<ruby>服务级别协议<rt>SLA</rt></ruby>和<ruby>服务质量<rt>QoS</rt></ruby>，例如弹性、应用程序性能、安全性等。</p><p><em>编程 PaaS</em>：允许应用程序与外部应用程序或公共云集成，并实现自动扩展和云爆发场景。</p><p><em>面向流程 PaaS</em>：允许通过创建持续交付流程来实现<ruby>开发运维<rt>DevOps</rt></ruby>流程，该流程可以自动构建、测试应用程序并将其交付到云环境中。</p><p>除了这些采用模式之外，还有其他的 PaaS 变体如下，这些变化可能与上文的模式有一定重合：</p><p><em>集成平台即服务（iPaaS）</em>：一套能够开发、执行和管理集成流的云服务。集成流可以是个人内部或跨多个组织连接的，可以包含任何企业内部或基于云的流程、服务、应用和数据。这些组合变化可能也符合上述的模式之一，例如 MuleSoft CloudHub 和 BizTalk。</p><p><em>移动平台即服务（mPaaS）</em>：为开发移动应用提供的集成开发环境（IDE），并且支持多种移动平台。</p><p><em>数据库平台即服务（dbPaas）</em>：一种按需的、安全且可扩展的自助式数据库平台，可自动配置和管理数据库。dbPaaS 使扩展数据库变得更加容易，并使它们更加可靠。</p><p><em>物联网平台即服务（IoTPaaS）</em>：提供了实现异构物联网拓扑所需的通信、安全、分析和管理的通用基础架构。它为构建物联网解决方案提供了更简单、更敏捷的模型。</p><p><em>业务流程管理平台即服务（bpmPaaS）</em>：一个完整的预集成业务流程管理平台，托管在云端并作为服务交付。它被用于开发和执行整个企业的业务流程和以工作流程为中心的应用程序。例如 Pega cloud 和 OpenText Cordys cloud。</p><p>PaaS 的一些基本特征：</p><ul><li>在同一集成开发环境中开发、测试、部署、托管和维护应用程序的服务</li><li>多租户架构，即多个并发用户使用同样的开发程序</li><li>部署软件的内置可扩展性，包括负载平衡和故障转移</li><li>与异构平台和系统的集成</li><li>支持开发团队的协作</li><li>包含处理帐单和管理订阅的工具</li></ul><h3 id="主要的开源-paas" tabindex="-1">主要的开源 PaaS <a class="header-anchor" href="#主要的开源-paas" aria-label="Permalink to “主要的开源 PaaS”">​</a></h3><p>在选择 PaaS 之前，企业主要考虑关注以下几点：</p><ul><li>部署灵活性</li><li>操作简便性</li><li>应用堆栈的选择</li><li>语言、数据库和框架支持</li><li>规模的可扩展性</li><li>服务质量（QoS）</li><li>开发和运营的工具</li><li>它有多适合你的业务</li></ul><p>现在让我们快速浏览下流行的开源 PaaS。</p><p><em>Cloud Foundry</em>：提供了多种云的选择、开发者框架和应用服务。Cloud Foundry 使构建、测试、部署和扩展应用程序变得更快、更容易。</p><p>它有不同的发行版本，其中比较流行的是 Pivotal 和 IBM。它包含应用<ruby>运行时<rt>runtime</rt></ruby>和容器运行时。在 Pivotal 上包含有应用服务和容器服务。</p><p><em>OpenShift</em>：红帽的云计算 PaaS 产品。这是一个云端的应用平台，应用开发者和团队可以在这里构建、测试、部署和运行他们的应用程序。</p><p><em>Cloudify</em>：在开放的原则下开发和设计，用以推动 IT 转型革命。它使组织能够在其上设计、建立和提供各种商业应用和网络服务。Cloudify 的最新版本为 4.3，它包含了先进的安全、控制和<ruby>真自服务<rt>true self-service</rt></ruby>等增强功能。Cloudify 4.3 还为 Kubernetes 容器编排引入了全新的概念。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">功能</th><th style="text-align:left;">Cloud Foundry</th><th style="text-align:left;">Cloudify</th><th style="text-align:left;">OpenShift</th></tr></thead><tbody><tr><td style="text-align:left;">核心功能</td><td style="text-align:left;">Cloud controller</td><td style="text-align:left;">Manager</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">提供第三方数据库服务</td><td style="text-align:left;">Service broker</td><td style="text-align:left;">Agent</td><td style="text-align:left;">Cartridge</td></tr><tr><td style="text-align:left;">传入流量的路由</td><td style="text-align:left;">Router</td><td style="text-align:left;">Manager</td><td style="text-align:left;">REST API</td></tr><tr><td style="text-align:left;">查询应用程序的状态</td><td style="text-align:left;">Cloud controller</td><td style="text-align:left;">CLI client</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">消息传递</td><td style="text-align:left;">Message bus</td><td style="text-align:left;">Manager</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">应用实例管理</td><td style="text-align:left;">Droplet execution agent</td><td style="text-align:left;">Agent</td><td style="text-align:left;">Node</td></tr><tr><td style="text-align:left;">应用程序状态管理</td><td style="text-align:left;">Health manager</td><td style="text-align:left;">Manager</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">Broker</td><td style="text-align:left;">Warden</td><td style="text-align:left;">Agent</td><td style="text-align:left;">Gear</td></tr><tr><td style="text-align:left;">用户请求的负载平衡</td><td style="text-align:left;">Droplet execution agent</td><td style="text-align:left;">Manager</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">框架提供者</td><td style="text-align:left;">Blob store</td><td style="text-align:left;">Agent</td><td style="text-align:left;">Cartridge</td></tr><tr><td style="text-align:left;">技术</td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">语言</td><td style="text-align:left;">Java, Ruby, Scala, Node.js, Groovy, Grails, PHP, Go, Python</td><td style="text-align:left;">Java, PHP, Ruby</td><td style="text-align:left;">Java, Ruby, Node.js, PHP, Python, Perl, JavaScript</td></tr><tr><td style="text-align:left;">数据库</td><td style="text-align:left;">MongoDB，MySQL</td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">MongoDB、MySQL、PostgreSQL</td><td style="text-align:left;">MySQL、MongoDB</td><td style="text-align:left;">MongoDB、MySQL、PostgreSQL</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">框架</td><td style="text-align:left;">Spring, Rails, Grails, Play Sinatra</td><td style="text-align:left;">JavaScript, Node.js</td><td style="text-align:left;">Rails, Flask, Django, Drupal, Vertx</td></tr><tr><td style="text-align:left;">水平扩展</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td></tr><tr><td style="text-align:left;">垂直扩展</td><td style="text-align:left;">是</td><td style="text-align:left;">否</td><td style="text-align:left;">是</td></tr><tr><td style="text-align:left;">弹性伸缩</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td></tr></tbody></table></div><p>表 1 列出了 Cloud Foundry、Cloudify 和 OpenShift 的基本功能及其对应的架构组件。以上完全基于个人观点，所支持的功能的真实需求应与云供应商进行验证。</p><p>从行业统计数据中，我们可以清楚地看出 PaaS 的使用率正在迅速上升。PaaS 使企业应用程序可以是<ruby>云无关<rt>cloud-agnostic</rt></ruby>的，它们可以在任何云平台上运行——无论是公共的还是私有的。这意味着一个在亚马逊的 AWS 上开发的应用可以很容易地移植到微软 Azure、VMWare vSphere、Red Hat RHEV 等等其他平台。</p><p>当多个开发人员共同参与一个开发项目，或外部用户需要与开发过程协作时，PaaS 是很有用的。因此，PaaS 尤其适合于敏捷开发，因为它降低了围绕软件快速开发和迭代的难度。</p><h3 id="鸣谢" tabindex="-1">鸣谢 <a class="header-anchor" href="#鸣谢" aria-label="Permalink to “鸣谢”">​</a></h3><p>作者感谢 Kiran M.R. 和 Wipro 有限公司的数字架构实践 Raju Alluri 为本文提供的支持。</p><hr>',37)),d("p",null,[t[1]||(t[1]=e("via: ",-1)),a(l,{href:"https://www.opensourceforu.com/2022/09/why-enterprises-should-opt-for-platform-as-a-service/"},{default:r(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/09/why-enterprises-should-opt-for-platform-as-a-service/",-1)])]),_:1})]),d("p",null,[t[6]||(t[6]=e("作者：",-1)),a(l,{href:"https://www.opensourceforu.com/author/gopalakrishna-behara/"},{default:r(()=>[...t[2]||(t[2]=[e("Gopala Krishna Behara",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),a(l,{href:"https://github.com/lkxed"},{default:r(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),a(l,{href:"https://github.com/onionstalgia"},{default:r(()=>[...t[4]||(t[4]=[e("onionstalgia",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),a(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),d("p",null,[t[12]||(t[12]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),a(l,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const C=i(p,[["render",y]]);export{h as __pageData,C as default};
